    .map(|_| ())
    .map_err(ReleaseStateError::EvidenceRejected)
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum ReleaseStateError {
    #[error("release state is bound to a different intent")]
    MismatchedIntent,
    #[error("release state operation roster differs from the bound intent")]
    MismatchedOperationRoster,
    #[error("release state carries an invalid run envelope: {0}")]
    InvalidEnvelope(ReleaseRunEnvelopeError),
    #[error("release state does not contain operation `{id:?}`")]
    UnknownOperation { id: Box<ReleaseOperationId> },
    #[error("operation `{id:?}`: {source}")]
    InvalidTransition {
        id: Box<ReleaseOperationId>,
        source: crate::release_transition::InvalidTransition,
    },
    #[error("successful release operation `{id:?}` carries no provider evidence")]
    MissingEvidence { id: Box<ReleaseOperationId> },
    #[error("release state evidence rejected: {0}")]
    EvidenceRejected(ProviderObservationError),
}

/// A terminal receipt derived only from a complete execution state.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReleaseReceiptV1 {
    schema_version: u8,
    intent_digest: IntentDigest,
    envelope: ReleaseRunEnvelopeV1,
    outcomes: BTreeMap<ReleaseOperationId, OperationOutcome>,
    observations: BTreeMap<ReleaseOperationId, ProviderObservationV1>,
}

#[derive(Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ReleaseReceiptV1Wire {
    schema_version: u8,
    intent_digest: IntentDigest,
    envelope: ReleaseRunEnvelopeV1,
    outcomes: Vec<OperationOutcomeEntryV1>,
    observations: Vec<ReleaseOperationObservationV1>,
}

#[derive(Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct OperationOutcomeEntryV1 {
    operation: ReleaseOperationId,
    outcome: OperationOutcome,
}

impl Serialize for ReleaseReceiptV1 {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        ReleaseReceiptV1Wire {
            schema_version: self.schema_version,
            intent_digest: self.intent_digest.clone(),
            envelope: self.envelope.clone(),
            outcomes: self
                .outcomes
                .iter()
                .map(|(operation, outcome)| OperationOutcomeEntryV1 {
                    operation: operation.clone(),
                    outcome: *outcome,
                })
                .collect(),
            observations: self
                .observations
                .iter()
                .map(|(operation, observation)| {
                    ReleaseOperationObservationV1::new(operation.clone(), observation.clone())
                        .expect("receipt observations were role-checked on construction")
                })
                .collect(),
        }
        .serialize(serializer)
    }
}

impl JsonSchema for ReleaseReceiptV1 {
    fn schema_name() -> String {
        "ReleaseReceiptV1".to_owned()
    }

    fn json_schema(generator: &mut schemars::gen::SchemaGenerator) -> schemars::schema::Schema {
        ReleaseReceiptV1Wire::json_schema(generator)
    }
}

impl<'de> Deserialize<'de> for ReleaseReceiptV1 {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseReceiptV1Wire::deserialize(deserializer)?;
        Self::from_wire(wire).map_err(serde::de::Error::custom)
    }
}

impl ReleaseReceiptV1 {
    pub const SCHEMA_VERSION: u8 = 2;

    /// Constructs a receipt from a terminal state alone: every operation must
    /// be successful, and its recorded evidence becomes its observation.
    ///
    /// The run envelope comes from the state, which was created and validated
    /// before the first effect; nothing is assembled after the fact here.
    pub fn from_state(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<Self, ReleaseReceiptError> {
        state
            .validate_for_intent(intent)
            .map_err(ReleaseReceiptError::InvalidState)?;
        let mut outcomes = BTreeMap::new();
        let mut observations = BTreeMap::new();
        for (id, operation_state) in &state.operations {
            let outcome = match operation_state {
                OperationState::Published => OperationOutcome::Published,
                OperationState::AlreadySatisfied => OperationOutcome::AlreadySatisfied,
                OperationState::Failed | OperationState::Blocked { .. } => {
                    return Err(ReleaseReceiptError::NonSuccessfulOperation {
                        id: Box::new(id.clone()),
                    });
                }
                OperationState::Pending | OperationState::Attempting => {
                    return Err(ReleaseReceiptError::NonTerminalOperation {
                        id: Box::new(id.clone()),
                    });
                }
            };
            let evidence = state.operation_evidence(id).cloned().ok_or_else(|| {
                ReleaseReceiptError::InvalidState(ReleaseStateError::MissingEvidence {
                    id: Box::new(id.clone()),
                })
            })?;
            outcomes.insert(id.clone(), outcome);
            observations.insert(id.clone(), ProviderObservationV1::Exact { evidence });
        }
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            intent_digest: state.intent_digest.clone(),
            envelope: state.envelope().clone(),
            outcomes,
            observations,
        })
    }

    /// The exact provider observation this receipt records for `id`.
    pub fn observation(&self, id: &ReleaseOperationId) -> Option<&ProviderObservationV1> {
        self.observations.get(id)
    }

    pub fn intent_digest(&self) -> &IntentDigest {
        &self.intent_digest
    }

    /// Validates exact intent and operation-roster binding before reconciliation.
    pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ReleaseReceiptError> {
        if self.schema_version != Self::SCHEMA_VERSION {
            return Err(ReleaseReceiptError::UnsupportedSchema {
                found: self.schema_version,
            });
        }
        if self.intent_digest != intent.digest {
            return Err(ReleaseReceiptError::MismatchedIntent);
        }
        self.envelope
            .validate_for_intent(intent)
            .map_err(ReleaseReceiptError::InvalidEnvelope)?;
        let expected: BTreeSet<_> = intent.operations.iter().map(|operation| operation.id.clone()).collect();
        let actual: BTreeSet<_> = self.outcomes.keys().cloned().collect();
        if actual != expected {
            return Err(ReleaseReceiptError::MismatchedOperationRoster);
        }
        let observed: BTreeSet<_> = self.observations.keys().cloned().collect();
        if observed != expected {
            return Err(ReleaseReceiptError::MismatchedObservationRoster);
        }
        if self
            .observations
            .values()
            .any(|observation| !observation.is_terminal_success())
        {
            return Err(ReleaseReceiptError::NonExactReceiptObservation);
        }
        Ok(())
    }

    fn from_wire(wire: ReleaseReceiptV1Wire) -> Result<Self, ReleaseReceiptError> {
        if wire.schema_version != Self::SCHEMA_VERSION {
            return Err(ReleaseReceiptError::UnsupportedSchema {
                found: wire.schema_version,
            });
        }
        let mut outcomes = BTreeMap::new();
        for entry in wire.outcomes {
            if !matches!(
                entry.outcome,
                OperationOutcome::Published | OperationOutcome::AlreadySatisfied
            ) {
                return Err(ReleaseReceiptError::NonSuccessfulOperation {
                    id: Box::new(entry.operation),
                });
            }
            if outcomes.insert(entry.operation.clone(), entry.outcome).is_some() {
                return Err(ReleaseReceiptError::DuplicateOperation {
                    id: Box::new(entry.operation),
                });
            }
        }
        let mut observations = BTreeMap::new();
        for entry in wire.observations {
            let (operation, observation) = entry.into_parts();
            if !observation.is_terminal_success() {
                return Err(ReleaseReceiptError::NonExactObservation {
                    id: Box::new(operation),
                    observation: Box::new(observation),
                });
            }
            if observations.insert(operation.clone(), observation).is_some() {
                return Err(ReleaseReceiptError::DuplicateObservation {
                    id: Box::new(operation),
                });
            }
        }
        Ok(Self {
            schema_version: wire.schema_version,
            intent_digest: wire.intent_digest,
            envelope: wire.envelope,
            outcomes,
            observations,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum ReleaseReceiptError {

item.stdout:
//! Deterministic, graph-owned release roster decisions.
//!
//! It records the exact package/version authority that later intent construction consumes, without
//! exposing a mutation route.

use callisto_model::{
    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
    ReleaseInclusionReason, ReleasePackageId, Version,
};

use crate::error::{
    CommandFailure, CommitVerificationFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason,
    UnsupportedReleaseFeature,
};
use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};

/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
/// against `package`'s name.
///
/// This is the single derivation of release package identity shared by every
/// site that computes or verifies release authority: [`derive_release_decision`],
/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
/// Per this module's own established lesson (see the doc comment on
/// [`derive_release_commit_decision`]), independently reimplementing this
/// mapping at each call site is exactly the kind of duplicated derivation
/// that drifts -- so it lives here once instead.
pub(crate) fn release_package_ids(
    identity: &crate::IdentityIndex,
    package: &Package,
) -> Result<Vec<ReleasePackageId>, GraphError> {
    package
        .canonical_manifests()
        .map(|manifest| {
            let ecosystem = manifest.ecosystem();
            // A dual-manifest package's manifests may declare different names.
            let name = identity
                .native_name(&package.id, ecosystem)
                .unwrap_or(package.id.name());
            ReleasePackageId::new(ecosystem, name)
        })
        .collect::<Result<Vec<_>, _>>()
        .map_err(GraphError::from)
}

/// Derives the durable roster from a freshly computed version plan.
///
/// The caller supplies the plan from the same workspace observation; this
/// function never inspects a caller-provided release roster.
pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
) -> Result<ReleaseDecisionV1, GraphError> {
    let mut package_ids = std::collections::BTreeMap::new();
    for package in workspace.graph.packages() {
        let ids = release_package_ids(&workspace.identity, package)?;
        package_ids.insert(package.id.clone(), ids);
    }

    let mut entries = Vec::new();
    for bump in &plan.bumps {
        // `plan` is contractually derived from this same workspace
        // observation (see doc comment above), so every bump's package must
        // already be a key here -- a miss means the plan/workspace pairing
        // itself is inconsistent, not a recoverable operator condition.
        let ids = package_ids
            .get(&bump.package)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!(
                    "version plan references package `{}`, which is absent from this workspace observation",
                    bump.package.display_name()
                ),
            })?;
        for id in ids {
            entries.push(ReleaseDecisionEntry {
                package: id.clone(),
                target_version: bump.to.clone(),
                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
            });
        }
    }
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Derives a durable decision for explicit, exact release identities.
///
/// A linked group is one release unit: selecting any member includes every
/// member of that linked group which the version plan selected. All other
/// packages remain outside the authority boundary. The caller must pass
/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
/// for release authority.
pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
    selections: &[ReleasePackageId],
) -> Result<ReleaseDecisionV1, GraphError> {
    let complete = derive_release_decision(workspace, plan)?;

    let mut seen = std::collections::BTreeSet::new();
    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
        return Err(GraphError::ReleaseSelectionInvalid {
            package: duplicate.clone(),
            reason: ReleaseSelectionInvalidReason::Duplicate,
        });
    }

    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    for selection in &selected {
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        let reason = if !complete.entries.iter().any(|entry| &entry.package == *selection) {
            ReleaseSelectionInvalidReason::NotARelease
        } else if package
            .publish_to
            .iter()
            .all(|target| matches!(target, callisto_model::PublishTarget::None))
        {
            ReleaseSelectionInvalidReason::NoDispatchableTarget
        } else {
            continue;
        };
        return Err(GraphError::ReleaseSelectionInvalid {
            package: (*selection).clone(),
            reason,
        });
    }

    let entries = expand_selection(workspace, complete.entries, &selected);
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Keeps the selected entries plus every entry sharing a fixed or linked group
/// with a selection. Both release routes narrow `--package` through this.
fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    entries: Vec<ReleaseDecisionEntry>,
    selected: &std::collections::BTreeSet<&ReleasePackageId>,
) -> Vec<ReleaseDecisionEntry> {
    // A plan-derived entry carries its linked group as a reason.
    let reason_groups = entries
        .iter()
        .filter(|entry| selected.contains(&entry.package))
        .flat_map(|entry| entry.reasons.iter())
        .filter_map(|reason| match reason {
            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
            _ => None,
        })
        .collect::<std::collections::BTreeSet<_>>();
    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
    let config_groups = selected
        .iter()
        .flat_map(|selection| release_groups_of(workspace, selection))
        .collect::<std::collections::BTreeSet<_>>();
    entries
        .into_iter()
        .filter(|entry| {
            selected.contains(&entry.package)
                || entry.reasons.iter().any(|reason| {
                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
                })
                || release_groups_of(workspace, &entry.package)
                    .iter()
                    .any(|group| config_groups.contains(group))
        })
        .collect()
}

/// Derives the roster of every publishable package whose current version has
/// no tag in the canonical [`crate::TagIndex`], each with
/// [`ReleaseInclusionReason::UnreleasedVersion`].
///
/// A non-empty `selections` restricts the roster to exactly those identities,
/// each of which must be unreleased and publishable. `None` means nothing is
/// unreleased.
pub fn derive_unreleased_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
) -> Result<Option<ReleaseDecisionV1>, GraphError> {
    let versions = workspace.base_versions()?;
    let tags = workspace.tags()?;
    let mut entries = Vec::new();
    for package in workspace.graph.packages() {
        if !has_dispatchable_target(package) {
            continue;
        }
        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!("package `{}` has no base version", package.id.display_name()),
        })?;
        if version_is_tagged(tags, &package.id, version) {
            continue;
        }
        for id in release_package_ids(&workspace.identity, package)? {
            entries.push(ReleaseDecisionEntry {
                package: id,
                target_version: version.clone(),
                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
            });
        }
    }

    let mut seen = std::collections::BTreeSet::new();
    for selection in selections {
        if !seen.insert(selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::Duplicate,
            });
        }
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        if !has_dispatchable_target(package) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
            });
        }
        if !entries.iter().any(|entry| &entry.package == selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NotARelease,
            });
        }
    }
    if !selections.is_empty() {
        entries = expand_selection(workspace, entries, &seen);
    }
    if entries.is_empty() {
        return Ok(None);
    }
    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
}

/// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
pub(crate) fn version_is_tagged(
    tags: &crate::TagIndex,
    package: &callisto_model::PackageId,
    version: &Version,
) -> bool {
    tags.contains_tag(&tags.template(package).render(version).to_string())
        || tags.last_tag(package).is_some_and(|tag| &tag.version == version)
}

pub(crate) fn has_dispatchable_target(package: &Package) -> bool {
    package
        .publish_to
        .iter()
        .any(|target| !matches!(target, callisto_model::PublishTarget::None))
}

/// The workspace package with this exact release identity.
fn workspace_package<'w, R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &'w Workspace<'_, R, D>,
    id: &ReleasePackageId,
) -> Option<&'w Package> {
    // By release identity, not name: a dual-manifest package's npm name can differ from its id.
    workspace
        .graph
        .packages()
        .find(|package| release_package_ids(&workspace.identity, package).is_ok_and(|ids| ids.contains(id)))
}

/// The fixed and linked groups a release package belongs to, per config.
fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    id: &ReleasePackageId,
) -> Vec<(&'static str, callisto_model::GroupName)> {
    let Some(package) = workspace_package(workspace, id) else {
        return Vec::new();
    };
    let groups = &workspace.config.groups;
    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
    // `member` keys are already canonical (`GroupTable::resolve` resolved
    // them through `IdentityIndex::resolve`), so exact equality is correct
    // here -- `PackageId::matches` would treat a Bare member key as an
    // ecosystem wildcard and could match a same-named package elsewhere.
    fixed
        .chain(linked)
        .filter(|(_, member, _)| **member == package.id)
        .map(|(kind, _, group)| (kind, group.clone()))
        .collect()
}

/// Verifies the release roster a merged release commit claims, against a
/// release-decision file committed alongside it at `decision_path`.
///
/// This is intentionally *not* a second computation of changeset, fixed-group,
/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
/// (via [`derive_release_decision`]) already computed that once, correctly,
/// when the release PR was generated -- and `callisto version --emit-decision`
/// commits its exact output alongside the manifest and changelog edits.
/// Re-deriving that policy a second time here, from raw git diffs, is exactly
/// the kind of duplicated logic that drifts: an earlier version of this
/// function did just that, understood only a direct changeset match, and
/// rejected every real release in this repository once a fixed-group cascade
/// (a case its reimplementation never learned) touched an unnamed sibling.
///
/// Instead, this function reads the committed decision back and confirms the
/// commit's actual diff matches it exactly -- no more, no less.
/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
/// entries don't match its content digest, so a hand-edited or corrupted
/// decision file fails before this function's own diff cross-check runs.
///
/// The caller must check out the exact merge commit in detached HEAD state
/// before creating an intent. GitHub-specific PR/approval provenance belongs
/// in the workflow boundary; this graph function verifies the local,
/// provider-neutral commit delta only.
pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    decision_path: &std::path::Path,
) -> Result<ReleaseDecisionV1, GraphError> {
    let head_args = ["rev-parse", "HEAD"];
    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
    let head =
        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
    if &head != release_commit {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::HeadMismatch,
        });
    }

    let parent_ref = format!("{}^", release_commit.as_str());
    let parent_args = ["rev-parse", parent_ref.as_str()];
    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;

    let diff_tree_args = [
        "diff-tree",
        "--no-commit-id",
        "--name-status",
        "-r",
        "--no-renames",
        parent.as_str(),
        release_commit.as_str(),
    ];
    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
    let changed = parse_name_status(&changed, &diff_tree_args)?;

    // The decision must be freshly authored as part of *this* commit, not a
    // stale leftover an earlier release already committed and this one never
    // touched -- otherwise a commit that changes nothing real could still
    // carry forward a prior, unrelated decision's authority.
    let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
    let decision_freshly_written = changed
        .iter()
        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
    if !decision_freshly_written {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
        });
    }

    // A cheap, independent sanity check that this commit is a real version
    // application and not just a hand-crafted decision file: some real
    // changeset was actually consumed. The decision's own entries, not this
    // changeset's content, remain the sole authority verified below.
    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
    let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
    let consumed_a_changeset = changed
        .iter()
        .any(|(status, path)| status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md"));
    if !consumed_a_changeset {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::NoChangesetConsumed,
        });
    }

    let decision_source = git_file(
        workspace.runner,
        &workspace.root,
        release_commit.as_str(),
        &decision_path_str,
    )?;
    let decision: ReleaseDecisionV1 =
        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
            path: decision_path.to_path_buf(),
            message: error.to_string(),
        })?;
    let claimed = decision
        .entries
        .iter()
        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
        .collect::<std::collections::BTreeMap<_, _>>();

    let changed_paths = changed
        .iter()
        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
        .collect::<std::collections::BTreeSet<_>>();

    // Every canonical manifest path this workspace currently declares, in
    // the exact order `workspace.graph.packages()` and
    // `Package::canonical_manifests()` yield -- both are backed by ordered
    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
    // the second traversal below visits the same (package, manifest) pairs
    // in the same order. That lets it zip the batched `before`/`after`
    // results back on by position instead of re-keying by path, which would
    // misbehave if two packages ever declared an identical manifest path.
    let manifest_queries: Vec<(String, Ecosystem)> = workspace
        .graph
        .packages()
        .flat_map(Package::canonical_manifests)
        .map(|manifest| (manifest.path.to_string_lossy().into_owned(), manifest.ecosystem()))
        .collect();
    let query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();

    // Exactly two `git cat-file --batch` subprocess invocations total (one
    // per commit), regardless of how many canonical manifests the
    // workspace has -- replaces what was previously 2*N separate `git
    // show` spawns (one `manifest_version_at` call per manifest per
    // commit).
    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
    let after_blobs =
        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
    let before_versions = resolve_batch_versions(before_blobs, &manifest_queries)?;
    let after_versions = resolve_batch_versions(after_blobs, &manifest_queries)?;

    let mut observed = std::collections::BTreeSet::new();
    let mut manifest_index = 0usize;
    for package in workspace.graph.packages() {
        let package_ids = release_package_ids(&workspace.identity, package)?;
        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
        if package_is_claimed {
            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
            })?;
            if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
                return Err(GraphError::ReleaseCommitVerificationFailed {
                    commit: release_commit.clone(),
                    reason: CommitVerificationFailure::ChangelogNotTouched,
                });
            }
        }
        for (manifest, id) in package.canonical_manifests().zip(package_ids) {
            let path = manifest.path.to_string_lossy();
            let before = &before_versions[manifest_index];
            let after = &after_versions[manifest_index];
            manifest_index += 1;
            let changed_version = before != after;
            match claimed.get(&id) {
                Some(target_version) => {
                    if !changed_paths.contains(path.as_ref()) {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestNotInDiff,
                        });
                    }
                    if !changed_version || after != target_version {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestVersionMismatch,
                        });
                    }
                    observed.insert(id);
                }
                None => {
                    if changed_version {
                        // A changed version the committed decision never
                        // claimed is not this commit's authority -- fail
                        // closed rather than trust a partial match.
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::UnclaimedVersionChange,
                        });
                    }
                }
            }
        }
    }
    if observed.len() != claimed.len() {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
        });
    }

    Ok(decision)
}

/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation that
/// exited non-zero, carrying its real exit status and stderr instead of
/// discarding them.
fn command_non_zero_exit(program: &str, args: &[&str], output: &callisto_model::CommandOutput) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::NonZeroExit {
            exit_code: output.exit_code,
            stderr: output.stderr.clone(),
        },
    }
}

/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation whose
/// output could not be parsed into the shape this module expects.
fn command_malformed_output(program: &str, args: &[&str], detail: impl Into<String>) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::MalformedOutput { detail: detail.into() },
    }
}

fn git_stdout<R: CommandRunner>(runner: &R, root: &std::path::Path, args: &[&str]) -> Result<String, GraphError> {
    let output = runner.run_with_timeout("git", args, root, super::release::timeouts::LOCAL_GIT)?;
    if !output.success() {
        return Err(command_non_zero_exit("git", args, &output));
    }
    Ok(output.stdout_trimmed().to_string())
}

fn parse_name_status(output: &str, args: &[&str]) -> Result<Vec<(String, String)>, GraphError> {
    output
        .lines()
        .map(|line| {
            let (status, path) = line.split_once('\t').ok_or_else(|| {
                command_malformed_output(
                    "git",
                    args,
                    format!("name-status line missing a tab separator: `{line}`"),
                )
            })?;
            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
                return Err(command_malformed_output(
                    "git",
                    args,
                    format!("name-status reported an unexpected status/path: `{status}` `{path}`"),
                ));
            }
            Ok((status.to_string(), path.to_string()))
        })
        .collect()
}

fn git_file<R: CommandRunner>(
    runner: &R,
    root: &std::path::Path,
    commit: &str,
    path: &str,
) -> Result<String, GraphError> {
    let object = format!("{commit}:{path}");
    git_stdout(runner, root, &["show", &object])
}

/// Extracts a manifest's declared version from its already-fetched raw
/// source text. Shared by the batched `git cat-file --batch` path in
/// [`derive_release_commit_decision`] (via [`resolve_batch_versions`]) and
/// this module's own tests (via the single-object `manifest_version_at`
/// helper they define), so both use identical parsing rules.
fn parse_manifest_version(source: &str, path: &str, ecosystem: Ecosystem) -> Result<Version, GraphError> {
    // Every canonical manifest this module ever queries comes from
    // `Package::canonical_manifests()`, which (per `walk.rs`) only ever
    // constructs a `Canonical`-role declaration for Cargo.toml/package.json/
    // pyproject.toml -- the three formats whose ecosystem always has a
    // `canonical_manifest_format`. A miss here means that upstream
    // invariant broke, not that this particular manifest is unsupported.
    let format = ecosystem
        .canonical_manifest_format()
        .ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!(
                "canonical manifest `{path}` has ecosystem `{}`, which has no canonical manifest format",
                ecosystem.prefix()
            ),
        })?;
    // A malformed blob, a version-less manifest (e.g. a Cargo workspace
    // root with no [package] table, or a `dynamic = ["version"]` PEP 621
    // package), or a Cargo `version.workspace = true` inheritance (which
    // `read_identity` deliberately never resolves, having no workspace
    // context for a historical git blob) all fail closed here rather than
    // panicking or fabricating a version.
    let version = callisto_manifests::read_identity(format, source, std::path::Path::new(path))
        .ok()
        .and_then(|identity| match identity.version {
            Some(callisto_manifests::VersionSource::Literal(v)) => Some(v),
            _ => None,
        })
        .ok_or_else(|| {
            command_malformed_output(
                "git",
                &["cat-file", "--batch"],
                format!("manifest `{path}` has no literal declared version"),
            )
        })?;
    Version::parse(&version, ecosystem.version_grammar()).map_err(GraphError::from)
}

/// One object's content as reported by `git cat-file --batch`, for a single
/// requested `<commit>:<path>`.
enum BatchBlob {
    /// The path resolved to a blob at the queried commit; this is its raw
    /// content.
    Blob(String),
    /// The path did not exist at the queried commit -- e.g. a package's
    /// manifest that was only added later, so it has no blob yet at an
    /// earlier `parent` commit.
    Missing,
}

/// Issues exactly one `git cat-file --batch` invocation requesting every
/// path in `paths` as `<commit>:<path>`, and returns each result in the
/// same order as `paths`.
///
/// `git cat-file --batch` reads one object identifier per line from stdin
/// and, for each, writes to stdout either:
///
/// ```text
/// <sha> SP <type> SP <size> LF
/// <content: exactly `size` bytes> LF
/// ```
///
/// or, if the object doesn't exist:
///
/// ```text
/// <object> SP missing LF
/// ```
///
/// (git also reports `<object> SP ambiguous LF` for a ref that resolves to
/// more than one object; `<commit>:<path>` syntax should never be
/// ambiguous, but it's checked for explicitly below rather than silently
/// falling through to the blob-header parse.)
///
/// This lets every canonical manifest's content at one commit be fetched in
/// a single subprocess round trip instead of one `git show` per manifest.
///
/// Parsing here is deliberately defensive rather than permissive: this
/// feeds [`derive_release_commit_decision`]'s trust-boundary comparison, so
/// any framing ambiguity -- an unrecognized header shape, a declared `size`
/// that doesn't fit the remaining output, a missing separator byte right
/// after the declared content length, a non-`blob` object type, or a
/// leftover/truncated tail once every requested path has been accounted
/// for -- fails the whole batch closed rather than guessing. Each expected
/// response is also matched against its exact requested object string
/// (rather than a generic "ends with ` missing`" pattern), so a manifest
/// path that happened to contain a space or colon can't be misread as a
/// different response shape. Silently misattributing one manifest's
/// content to a different path because an undetected desync shifted every
/// later offset would be a far worse failure mode than an outright
/// rejection.
fn batch_manifest_blobs_at<R: CommandRunner>(
    runner: &R,
    root: &std::path::Path,
    commit: &str,
    paths: &[&str],
) -> Result<Vec<BatchBlob>, GraphError> {
    if paths.is_empty() {
        return Ok(Vec::new());
    }

    const BATCH_ARGS: [&str; 2] = ["cat-file", "--batch"];

    let mut stdin = String::new();
    let objects: Vec<String> = paths
        .iter()
        .map(|path| {
            let object = format!("{commit}:{path}");
            stdin.push_str(&object);
            stdin.push('\n');
            object
        })
        .collect();

    let output = runner.run_with_stdin("git", &BATCH_ARGS, root, stdin.as_bytes())?;
    if !output.success() {
        return Err(command_non_zero_exit("git", &BATCH_ARGS, &output));
    }

    let mut rest = output.stdout.as_str();
    let mut results = Vec::with_capacity(objects.len());
    for object in &objects {
        let (header, after_header) = rest.split_once('\n').ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("truncated response: missing header line for `{object}`"),
            )
        })?;

        if header == format!("{object} missing") {
            results.push(BatchBlob::Missing);
            rest = after_header;
            continue;
        }
        if header == format!("{object} ambiguous") {
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` is ambiguous"),
            ));
        }

        let mut fields = header.split(' ');
        let sha = fields.next().ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` is missing its sha field: `{header}`"),
            )
        })?;
        let object_type = fields.next().ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` is missing its type field: `{header}`"),
            )
        })?;
        let size_field = fields.next().ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` is missing its size field: `{header}`"),
            )
        })?;
        if fields.next().is_some() {
            // A well-formed header has exactly three space-separated
            // fields; anything else is not a shape this parser understands.
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` has more than three fields: `{header}`"),
            ));
        }
        if sha.is_empty() || !sha.chars().all(|c| c.is_ascii_hexdigit()) {
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` reports a non-hex sha: `{sha}`"),
            ));
        }
        if object_type != "blob" {
            // Every path requested here is a canonical manifest file, so a
            // resolved object must be a blob; a tree/commit/tag response
            // means the path resolved to something else entirely.
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` resolved to a `{object_type}`, not a blob"),
            ));
        }
        let size: usize = size_field.parse().map_err(|parse_error| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` has a non-numeric size `{size_field}`: {parse_error}"),
            )
        })?;

        if size > after_header.len() {
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` declares size {size}, exceeding the remaining response"),
            ));
        }
        // `.get(..size)` (byte-indexed) rather than raw slicing: if `size`
        // doesn't land on a UTF-8 char boundary this fails closed instead
        // of panicking.
        let content = after_header.get(..size).ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` declares size {size} that does not land on a UTF-8 boundary"),
            )
        })?;
        let remainder = &after_header[size..];
        // The protocol always emits exactly one LF right after the
        // content, separate from the content itself. Requiring it here
        // catches a desynced `size` (from an earlier, unexpectedly
        // reencoded entry) as an explicit error instead of silently
        // parsing the wrong bytes as this entry's content.
        if remainder.as_bytes().first() != Some(&b'\n') {
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` content is not followed by the expected newline separator"),
            ));
        }
        results.push(BatchBlob::Blob(content.to_string()));
        rest = &remainder[1..];
    }

    if !rest.is_empty() {
        // More output than the requested objects account for -- either an
        // extra unexpected reply or a framing desync earlier in the
        // stream. Either way, fail closed rather than ignore it.
        return Err(command_malformed_output(
            "git",
            &BATCH_ARGS,
            "response contained more data than the requested objects account for",
        ));
    }

    Ok(results)
}

/// Converts each batched blob-fetch result into the [`Version`] the
/// equivalent single-object `git show` fetch would have produced, using
/// [`parse_manifest_version`]'s parsing rules. A path missing from the
/// queried commit fails closed exactly as a `git show` that couldn't
/// resolve the path would have.
fn resolve_batch_versions(blobs: Vec<BatchBlob>, queries: &[(String, Ecosystem)]) -> Result<Vec<Version>, GraphError> {
    blobs
        .into_iter()
        .zip(queries.iter())
        .map(|(blob, (path, ecosystem))| match blob {
            BatchBlob::Blob(source) => parse_manifest_version(&source, path, *ecosystem),
            BatchBlob::Missing => Err(command_malformed_output(
                "git",
                &["cat-file", "--batch"],
                format!("canonical manifest `{path}` was reported missing at the queried commit"),
            )),
        })
        .collect()
}

fn reason_from_bump(
    reason: Option<&BumpReason>,
    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
) -> Result<ReleaseInclusionReason, GraphError> {
    match reason {
        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
            group_id: group.to_string(),
        }),
        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
            Ok(ReleaseInclusionReason::FixedGroup {
                group_id: group.to_string(),
            })
        }
        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
            // `package_ids` is derived from the same workspace graph `via`
            // was resolved against, so a miss (or a non-unique release
            // identity) here means that pairing broke, not that this is a
            // recoverable operator condition.
            let source = package_ids
                .get(via)
                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!(
                        "cascade source package `{}` has no unique release package id",
                        via.display_name()
                    ),
                })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: format!("{dep_kind:?}"),
            })
        }
        Some(BumpReason::PeerEscalation { via, .. }) => {
            let source = package_ids
                .get(via)
                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!(
                        "peer-escalation source package `{}` has no unique release package id",
                        via.display_name()
                    ),
                })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: "peer".to_string(),
            })
        }
        Some(_) => Err(GraphError::UnsupportedRelease {
            feature: UnsupportedReleaseFeature::BumpReason,
        }),
    }
}

#[cfg(test)]
mod tests {
    use callisto_model::{Ecosystem, Version};

    use super::*;

    #[test]
    fn decision_is_canonical_and_ecosystem_qualified() {
        let cargo = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
        let npm = ReleasePackageId::new(Ecosystem::Npm, "demo").unwrap();
        let first = ReleaseDecisionV1::new(vec![
            ReleaseDecisionEntry {
                package: npm,
                target_version: Version::semver(1, 0, 0),
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            },
            ReleaseDecisionEntry {
                package: cargo,
                target_version: Version::semver(1, 0, 0),
                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
            },
        ])
        .unwrap();
        assert_eq!(first.entries[0].package.to_string(), "cargo/demo");
        assert_ne!(first.entries[0].package, first.entries[1].package);
    }

    #[test]
    fn release_commit_delta_parser_accepts_only_unambiguous_path_statuses() {
        let args = ["diff-tree", "--name-status"];
        assert_eq!(
            parse_name_status("M\tCargo.toml\nD\t.changeset/release.md\n", &args).unwrap(),
            vec![
                ("M".to_string(), "Cargo.toml".to_string()),
                ("D".to_string(), ".changeset/release.md".to_string()),
            ]
        );
        assert!(parse_name_status("R100\told\tnew\n", &args).is_err());
        assert!(parse_name_status("M Cargo.toml\n", &args).is_err());
    }

    /// Regression: both malformed name-status lines must
    /// surface as `GraphError::ReleaseCommand` (E164) with a
    /// `CommandFailure::MalformedOutput` cause naming the real `git`
    /// program/args, not the old fieldless `ReleaseIntentStale`.
    #[test]
    fn release_commit_delta_parser_reports_malformed_output_not_stale_intent() {
        let args = ["diff-tree", "--name-status"];
        let err = parse_name_status("R100\told\tnew\n", &args).unwrap_err();
        match err {
            GraphError::ReleaseCommand {
                program,
                failure: CommandFailure::MalformedOutput { .. },
                ..
            } => assert_eq!(program, "git"),
            other => panic!("expected ReleaseCommand{{failure: MalformedOutput}}, got {other:?}"),
        }
    }

    struct FixedBlobRunner(&'static str);

    impl CommandRunner for FixedBlobRunner {
        fn run(
            &self,
            _program: &str,
            _args: &[&str],
            _cwd: &std::path::Path,
        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
            Ok(callisto_model::CommandOutput {
                exit_code: Some(0),
                stdout: self.0.to_string(),
                stderr: String::new(),
            })
        }
    }

    /// Test-only: single-object equivalent of the batched
    /// `git cat-file --batch` path production code now uses (see
    /// `batch_manifest_blobs_at`/`resolve_batch_versions`), kept only so
    /// the two tests below can exercise `parse_manifest_version`'s parsing
    /// rules through a `CommandRunner` + single `git show` fetch, matching
    /// how they were originally written.
    fn manifest_version_at<R: CommandRunner>(
        runner: &R,
        root: &std::path::Path,
        commit: &str,
        path: &str,
        ecosystem: Ecosystem,
    ) -> Result<Version, GraphError> {
        let source = git_file(runner, root, commit, path)?;
        parse_manifest_version(&source, path, ecosystem)
    }

    // toml_edit's `Index` impl panics on a missing table ("index not found")
    // rather than returning None -- manifest_version_at previously used it
    // directly (`document["project"]["version"]`), so a Poetry-only
    // pyproject.toml, a PEP 621 `dynamic = ["version"]` package, or a
    // `Cargo.toml` with no `[package]` table would abort release-commit
    // verification with a panic instead of failing closed.
    #[test]
    fn manifest_version_at_fails_closed_instead_of_panicking_on_missing_tables() {
        let cases: &[(&str, Ecosystem)] = &[
            ("[project]\nname = \"x\"\ndynamic = [\"version\"]\n", Ecosystem::Pypi),
            ("[workspace]\nmembers = [\"a\"]\n", Ecosystem::Cargo),
        ];
        for (source, ecosystem) in cases {
            let runner = FixedBlobRunner(source);
            let result = manifest_version_at(&runner, std::path::Path::new("."), "deadbeef", "Cargo.toml", *ecosystem);
            assert!(
                matches!(
                    result,
                    Err(GraphError::ReleaseCommand {
                        failure: CommandFailure::MalformedOutput { .. },
                        ..
                    })
                ),
                "expected a clean ReleaseCommand{{MalformedOutput}} rejection (not a panic) for {ecosystem:?}, got {result:?}"
            );
        }
    }

    #[test]
    fn manifest_version_at_still_resolves_poetry_fallback_and_normal_cargo() {
        let poetry = FixedBlobRunner("[tool.poetry]\nname = \"x\"\nversion = \"1.0.0\"\n");
        assert_eq!(
            manifest_version_at(
                &poetry,
                std::path::Path::new("."),
                "deadbeef",
                "pyproject.toml",
                Ecosystem::Pypi
            )
            .unwrap(),
            Version::parse("1.0.0", Ecosystem::Pypi.version_grammar()).unwrap()
        );

        let cargo = FixedBlobRunner("[package]\nname = \"x\"\nversion = \"1.2.3\"\n");
        assert_eq!(
            manifest_version_at(
                &cargo,
                std::path::Path::new("."),
                "deadbeef",
                "Cargo.toml",
                Ecosystem::Cargo
            )
            .unwrap(),
            Version::semver(1, 2, 3)
        );
    }

    /// A minimal fake [`DependencyResolver`] exposing a fixed set of
    /// packages, each with one canonical Cargo manifest and a changelog --
    /// just enough shape for [`derive_release_commit_decision`] to walk.
    struct FixedManifestGraph {
        packages: Vec<Package>,
    }

    impl DependencyResolver for FixedManifestGraph {
        fn packages(&self) -> impl Iterator<Item = &Package> {
            self.packages.iter()
        }

        fn dependencies_of(&self, _id: &callisto_model::PackageId) -> impl Iterator<Item = &callisto_model::DepEdge> {
            std::iter::empty()
        }

        fn dependents_of(&self, _id: &callisto_model::PackageId) -> impl Iterator<Item = &callisto_model::DepEdge> {
            std::iter::empty()
        }
    }

    fn cargo_package(name: &str) -> Package {
        Package {
            id: callisto_model::PackageId::parse(&format!("cargo:{name}")).unwrap(),
            manifests: vec![callisto_model::ManifestDecl::new(
                format!("{name}/Cargo.toml"),
                callisto_model::ManifestRole::Canonical,
                callisto_model::ManifestFormat::CargoToml,
            )
            .unwrap()],
            changelog: Some(std::path::PathBuf::from(format!("{name}/CHANGELOG.md"))),
            release_trigger: callisto_model::ReleaseTrigger::Changeset,
            publish_to: Vec::new(),
            tag_template: None,
        }
    }

    fn publishing_cargo_package(name: &str) -> Package {
        Package {
            publish_to: vec![callisto_model::PublishTarget::CratesIo],
            ..cargo_package(name)
        }
    }

    fn cargo_manifest_source(name: &str, version: &str) -> String {
        format!("[package]\nname = \"{name}\"\nversion = \"{version}\"\n")
    }

    /// Records every `run`/`run_with_stdin` invocation and answers each the
    /// way a real `git` would for this test's fixed fixture, so
    /// `derive_release_commit_decision` can be driven entirely in-memory.
    /// `batch_calls` is the assertion this test cares about: it must land
    /// on exactly 2 (one `cat-file --batch` per commit) no matter how many
    /// canonical manifests `FixedManifestGraph` declares, proving the fix
    /// replaced 2*N `git show` spawns with 2 total, not N-scaled batches.
    struct CountingBatchRunner {
        release_commit: String,
        parent: String,
        decision_json: String,
        name_status: String,
        /// (commit, path) -> blob content; a path/commit pair with no entry
        /// here is answered as `missing`, matching real `git cat-file
        /// --batch` behavior for a path that doesn't exist at that commit.
        blobs: std::collections::BTreeMap<(String, String), String>,
        run_calls: std::sync::Mutex<Vec<(String, Vec<String>)>>,
        batch_calls: std::sync::Mutex<u32>,
    }

    impl CommandRunner for CountingBatchRunner {
        fn run(
            &self,
            program: &str,
            args: &[&str],
            _cwd: &std::path::Path,
        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
            self.run_calls
                .lock()
                .unwrap()
                .push((program.to_string(), args.iter().map(|s| s.to_string()).collect()));

            let ok = |stdout: String| {
                Ok(callisto_model::CommandOutput {
                    exit_code: Some(0),
                    stdout,
                    stderr: String::new(),
                })
            };
            let rev_parse_parent = format!("{}^", self.release_commit);
            let decision_object = format!("{}:.callisto/release-decision.json", self.release_commit);
            if args.first().copied() == Some("rev-parse") && args.get(1).copied() == Some("HEAD") {
                return ok(self.release_commit.clone());
            }
            if args.first().copied() == Some("rev-parse") && args.get(1).copied() == Some(rev_parse_parent.as_str()) {
                return ok(self.parent.clone());
            }
            if args.first().copied() == Some("diff-tree") {
                return ok(self.name_status.clone());
            }
            if args.first().copied() == Some("show") && args.get(1).copied() == Some(decision_object.as_str()) {
                return ok(self.decision_json.clone());
            }
            panic!("unexpected `{program} {args:?}` in CountingBatchRunner::run");
        }

        fn run_with_stdin(
            &self,
            program: &str,
            args: &[&str],
            _cwd: &std::path::Path,
            stdin: &[u8],
        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
            self.run_calls
                .lock()
                .unwrap()
                .push((program.to_string(), args.iter().map(|s| s.to_string()).collect()));
            assert_eq!(program, "git");
            assert_eq!(args, ["cat-file", "--batch"]);
            *self.batch_calls.lock().unwrap() += 1;

            let requested = std::str::from_utf8(stdin).expect("test stdin is always valid UTF-8");
            let mut stdout = String::new();
            for object in requested.lines() {
                let (commit, path) = object.split_once(':').expect("object identifier must be commit:path");
                match self.blobs.get(&(commit.to_string(), path.to_string())) {
                    Some(content) => {
                        stdout.push_str(&format!("{} blob {}\n{}\n", "0".repeat(40), content.len(), content));
                    }
                    None => {
                        stdout.push_str(&format!("{object} missing\n"));
                    }
                }
            }
            Ok(callisto_model::CommandOutput {
                exit_code: Some(0),
                stdout,
                stderr: String::new(),
            })
        }
    }

    /// Builds a `Workspace` wired to `runner` and `packages`, matching the
    /// fixture every `derive_release_commit_decision` test in this module
    /// shares.
    fn fixture_workspace<'a>(
        runner: &'a CountingBatchRunner,
        packages: Vec<Package>,
    ) -> Workspace<'a, CountingBatchRunner, FixedManifestGraph> {
        let config = crate::config::load(std::path::Path::new("/nonexistent-test-root")).unwrap();
        let graph = FixedManifestGraph { packages };
        Workspace {
            root: std::path::PathBuf::from("/nonexistent-test-root"),
            config,
            graph,
            tags: std::cell::OnceCell::new(),
            git: std::cell::OnceCell::new(),
            runner,
            manifest_cache: Default::default(),
            identity: crate::IdentityIndex::default(),
        }
    }

    /// AC: for a release commit touching multiple canonical manifests,
    /// `derive_release_commit_decision` issues exactly 2 `git cat-file
    /// --batch` invocations (one per commit) -- not 2*N separate `git show`
    /// spawns, one per manifest per commit, as the pre-fix implementation
    /// did.
    #[test]
    fn derive_release_commit_decision_issues_exactly_two_batch_invocations_for_multiple_manifests() {
        let release_commit_sha = "a".repeat(40);
        let parent_sha = "b".repeat(40);

        let packages = vec![cargo_package("pkg-a"), cargo_package("pkg-b"), cargo_package("pkg-c")];

        let bumps = [
            ("pkg-a", "1.0.0", "1.1.0"),
            ("pkg-b", "2.0.0", "2.1.0"),
            ("pkg-c", "3.0.0", "3.1.0"),
        ];

        let mut blobs = std::collections::BTreeMap::new();
        let mut entries = Vec::new();
        for (name, before, after) in bumps {
            let path = format!("{name}/Cargo.toml");
            blobs.insert((parent_sha.clone(), path.clone()), cargo_manifest_source(name, before));
            blobs.insert((release_commit_sha.clone(), path), cargo_manifest_source(name, after));
            let target = Version::parse(after, Ecosystem::Cargo.version_grammar()).unwrap();
            entries.push(ReleaseDecisionEntry {
                package: ReleasePackageId::new(Ecosystem::Cargo, name).unwrap(),
                target_version: target,
                reasons: vec![ReleaseInclusionReason::Changeset],
            });
        }
        let decision = ReleaseDecisionV1::new(entries).unwrap();
        let decision_json = serde_json::to_string(&decision).unwrap();

        let name_status = [
            "A\t.callisto/release-decision.json".to_string(),
            "D\t.changeset/multi-pkg-minor.md".to_string(),
            "M\tpkg-a/Cargo.toml".to_string(),
            "M\tpkg-a/CHANGELOG.md".to_string(),
            "M\tpkg-b/Cargo.toml".to_string(),
            "M\tpkg-b/CHANGELOG.md".to_string(),
            "M\tpkg-c/Cargo.toml".to_string(),
            "M\tpkg-c/CHANGELOG.md".to_string(),
        ]
        .join("\n");

        let runner = CountingBatchRunner {
            release_commit: release_commit_sha.clone(),
            parent: parent_sha,
            decision_json,
            name_status,
            blobs,
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        };

        let workspace = fixture_workspace(&runner, packages);

        let release_commit = CommitSha::parse(&release_commit_sha).unwrap();
        let decision_path = std::path::Path::new(".callisto/release-decision.json");
        let result = derive_release_commit_decision(&workspace, &release_commit, decision_path);

        assert!(result.is_ok(), "expected Ok, got {result:?}");
        assert_eq!(
            *runner.batch_calls.lock().unwrap(),
            2,
            "expected exactly 2 `git cat-file --batch` invocations (one per commit) for 3 \
             canonical manifests, not one per manifest per commit"
        );
    }

    /// A merged commit whose actual `HEAD` differs from the commit
    /// being verified must report `ReleaseCommitVerificationFailed{reason:
    /// HeadMismatch}`, naming the *verified* commit -- not the fieldless
    /// `ReleaseIntentStale` every other mismatch used to collapse into.
    #[test]
    fn derive_release_commit_decision_reports_head_mismatch_distinctly() {
        let actual_head = "a".repeat(40);
        let claimed_commit = "c".repeat(40);

        let runner = CountingBatchRunner {
            release_commit: actual_head,
            parent: "b".repeat(40),
            decision_json: String::new(),
            name_status: String::new(),
            blobs: std::collections::BTreeMap::new(),
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        };
        let workspace = fixture_workspace(&runner, vec![]);

        let release_commit = CommitSha::parse(&claimed_commit).unwrap();
        let decision_path = std::path::Path::new(".callisto/release-decision.json");
        let err = derive_release_commit_decision(&workspace, &release_commit, decision_path).unwrap_err();

        match err {
            GraphError::ReleaseCommitVerificationFailed { commit, reason } => {
                assert_eq!(commit, release_commit);
                assert_eq!(reason, CommitVerificationFailure::HeadMismatch);
            }
            other => panic!("expected ReleaseCommitVerificationFailed{{HeadMismatch}}, got {other:?}"),
        }
    }

    /// A committed decision file that isn't valid JSON must report
    /// `ReleaseDecisionDecode` naming the decision path -- distinct from
    /// every `ReleaseCommitVerificationFailed` mismatch, and distinct from
    /// the old fieldless `ReleaseIntentStale` both used to share.
    #[test]
    fn derive_release_commit_decision_reports_corrupt_decision_file_distinctly() {
        let release_commit_sha = "a".repeat(40);
        let parent_sha = "b".repeat(40);
        let packages = vec![cargo_package("pkg-a")];

        let name_status = [
            "A\t.callisto/release-decision.json".to_string(),
            "D\t.changeset/multi-pkg-minor.md".to_string(),
            "M\tpkg-a/Cargo.toml".to_string(),
            "M\tpkg-a/CHANGELOG.md".to_string(),
        ]
        .join("\n");

        let runner = CountingBatchRunner {
            release_commit: release_commit_sha.clone(),
            parent: parent_sha,
            decision_json: "{ not valid json".to_string(),
            name_status,
            blobs: std::collections::BTreeMap::new(),
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        };
        let workspace = fixture_workspace(&runner, packages);

        let release_commit = CommitSha::parse(&release_commit_sha).unwrap();
        let decision_path = std::path::Path::new(".callisto/release-decision.json");
        let err = derive_release_commit_decision(&workspace, &release_commit, decision_path).unwrap_err();

        match err {
            GraphError::ReleaseDecisionDecode { path, .. } => {
                assert_eq!(path, decision_path);
            }
            other => panic!("expected ReleaseDecisionDecode, got {other:?}"),
        }
    }

    /// A committed decision claiming a release package this
    /// workspace never observes changing must report
    /// `ReleaseCommitVerificationFailed{reason: ClaimedPackageNotObserved}`,
    /// distinct from every other mismatch this function can report.
    #[test]
    fn derive_release_commit_decision_reports_claimed_package_not_observed_distinctly() {
        let release_commit_sha = "a".repeat(40);
        let parent_sha = "b".repeat(40);
        let packages = vec![cargo_package("pkg-a")];

        let mut blobs = std::collections::BTreeMap::new();
        blobs.insert(
            (parent_sha.clone(), "pkg-a/Cargo.toml".to_string()),
            cargo_manifest_source("pkg-a", "1.0.0"),
        );
        blobs.insert(
            (release_commit_sha.clone(), "pkg-a/Cargo.toml".to_string()),
            cargo_manifest_source("pkg-a", "1.1.0"),
        );

        let entries = vec![
            ReleaseDecisionEntry {
                package: ReleasePackageId::new(Ecosystem::Cargo, "pkg-a").unwrap(),
                target_version: Version::semver(1, 1, 0),
                reasons: vec![ReleaseInclusionReason::Changeset],
            },
            ReleaseDecisionEntry {
                package: ReleasePackageId::new(Ecosystem::Npm, "pkg-ghost").unwrap(),
                target_version: Version::semver(1, 0, 0),
                reasons: vec![ReleaseInclusionReason::Changeset],
            },
        ];
        let decision = ReleaseDecisionV1::new(entries).unwrap();
        let decision_json = serde_json::to_string(&decision).unwrap();

        let name_status = [
            "A\t.callisto/release-decision.json".to_string(),
            "D\t.changeset/multi-pkg-minor.md".to_string(),
            "M\tpkg-a/Cargo.toml".to_string(),
            "M\tpkg-a/CHANGELOG.md".to_string(),
        ]
        .join("\n");

        let runner = CountingBatchRunner {
            release_commit: release_commit_sha.clone(),
            parent: parent_sha,
            decision_json,
            name_status,
            blobs,
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        };
        let workspace = fixture_workspace(&runner, packages);

        let release_commit = CommitSha::parse(&release_commit_sha).unwrap();
        let decision_path = std::path::Path::new(".callisto/release-decision.json");
        let err = derive_release_commit_decision(&workspace, &release_commit, decision_path).unwrap_err();

        match err {
            GraphError::ReleaseCommitVerificationFailed { commit, reason } => {
                assert_eq!(commit, release_commit);
                assert_eq!(reason, CommitVerificationFailure::ClaimedPackageNotObserved);
            }
            other => panic!("expected ReleaseCommitVerificationFailed{{ClaimedPackageNotObserved}}, got {other:?}"),
        }
    }

    /// A plan bumping exactly `package_name` (a `cargo:` package), so
    /// `derive_release_decision` produces a real, non-empty roster instead
    /// of failing on `ReleaseDecisionError::EmptyRoster` before the
    /// selection-validation logic under test ever runs.
    /// Fixed groups version in lockstep: narrowing to one member must keep its
    /// siblings, or a sibling's release artifact fails ArtifactSlotOutsideDecision
    /// and a bumped sibling is left unpublished (the 0.6-0.7 failure shape).
    #[test]
    fn selecting_one_fixed_group_member_retains_its_lockstep_siblings() {
        let runner = CountingBatchRunner {
            release_commit: "a".repeat(40),
            parent: "b".repeat(40),
            decision_json: String::new(),
            name_status: String::new(),
            blobs: std::collections::BTreeMap::new(),
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        };
        let mut workspace = fixture_workspace(
            &runner,
            vec![
                publishing_cargo_package("cli"),
                cargo_package("plugin"),
                cargo_package("other"),
            ],
        );
        let group = callisto_model::GroupName("workspace".to_string());
        for name in ["cli", "plugin"] {
            workspace.config.groups.fixed_of.insert(
                callisto_model::PackageId::parse(&format!("cargo:{name}")).unwrap(),
                group.clone(),
            );
        }
        let bump = |name: &str, reason: BumpReason| crate::PlannedBump {
            package: callisto_model::PackageId::parse(&format!("cargo:{name}")).unwrap(),
            from: Version::semver(1, 0, 0),
            to: Version::semver(1, 1, 0),
            severity: callisto_model::Severity::Minor,
            governed_by: None,
            reason: Some(reason),
            writes: vec![],
        };
        let plan = VersionPlan {
            bumps: vec![
                bump("cli", BumpReason::Changeset { changesets: vec![] }),
                bump("plugin", BumpReason::FixedGroupUnion { group: group.clone() }),
                bump("other", BumpReason::Changeset { changesets: vec![] }),
            ],
            ..Default::default()
        };
        let cli = ReleasePackageId::new(Ecosystem::Cargo, "cli").unwrap();

        let decision = derive_selected_release_decision(&workspace, &plan, &[cli]).unwrap();

        let released: Vec<String> = decision.entries.iter().map(|e| e.package.to_string()).collect();
        assert!(
            released.iter().any(|p| p.ends_with("plugin")),
            "fixed sibling dropped: {released:?}"
        );
        assert!(
            !released.iter().any(|p| p.ends_with("other")),
            "unrelated package kept: {released:?}"
        );
    }

    fn plan_bumping(package_name: &str) -> VersionPlan {
        VersionPlan {
            bumps: vec![crate::PlannedBump {
                package: callisto_model::PackageId::parse(&format!("cargo:{package_name}")).unwrap(),
                from: Version::semver(1, 0, 0),
                to: Version::semver(1, 1, 0),
                severity: callisto_model::Severity::Minor,
                governed_by: None,
                reason: Some(BumpReason::Changeset { changesets: vec![] }),
                writes: vec![],
            }],
            ..Default::default()
        }
    }

    /// A duplicate `--package` selection must report
    /// `ReleaseSelectionInvalid{reason: Duplicate}` naming the duplicated
    /// package, not the fieldless `ReleaseIntentStale`.
    #[test]
    fn derive_selected_release_decision_reports_duplicate_selection_distinctly() {
        let package = ReleasePackageId::new(Ecosystem::Cargo, "pkg-a").unwrap();
        let runner = CountingBatchRunner {
            release_commit: "a".repeat(40),
            parent: "b".repeat(40),
            decision_json: String::new(),
            name_status: String::new(),
            blobs: std::collections::BTreeMap::new(),
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        };
        let workspace = fixture_workspace(&runner, vec![cargo_package("pkg-a")]);
        let plan = plan_bumping("pkg-a");

        let err = derive_selected_release_decision(&workspace, &plan, &[package.clone(), package.clone()]).unwrap_err();
        match err {
            GraphError::ReleaseSelectionInvalid {
                package: reported,
                reason,
            } => {
                assert_eq!(reported, package);
                assert_eq!(reason, ReleaseSelectionInvalidReason::Duplicate);
            }
            other => panic!("expected ReleaseSelectionInvalid{{Duplicate}}, got {other:?}"),
        }
    }

    fn empty_runner() -> CountingBatchRunner {
        CountingBatchRunner {
            release_commit: "a".repeat(40),
            parent: "b".repeat(40),
            decision_json: String::new(),
            name_status: String::new(),
            blobs: std::collections::BTreeMap::new(),
            run_calls: std::sync::Mutex::new(Vec::new()),
            batch_calls: std::sync::Mutex::new(0),
        }
    }

    fn selection_error(workspace_packages: Vec<Package>, bumped: &str, selection: &str) -> GraphError {
        let runner = empty_runner();
        let workspace = fixture_workspace(&runner, workspace_packages);
        let selection = ReleasePackageId::new(Ecosystem::Cargo, selection).unwrap();
        derive_selected_release_decision(&workspace, &plan_bumping(bumped), std::slice::from_ref(&selection))
            .unwrap_err()
    }

    /// A workspace package with no pending release is `NotARelease`.
    #[test]
    fn selection_that_is_not_a_release_candidate_reports_not_a_release() {
        let err = selection_error(
            vec![publishing_cargo_package("pkg-a"), publishing_cargo_package("pkg-b")],
            "pkg-b",
            "pkg-a",
        );
        assert!(
            matches!(
                &err,
                GraphError::ReleaseSelectionInvalid { package, reason: ReleaseSelectionInvalidReason::NotARelease }
                    if package.name() == "pkg-a"
            ),
            "{err:?}"
        );
    }

    /// A release candidate with nothing to dispatch is `NoDispatchableTarget`.
    #[test]
    fn release_candidate_without_publish_target_reports_no_dispatchable_target() {
        let err = selection_error(vec![cargo_package("pkg-a")], "pkg-a", "pkg-a");
        assert!(
            matches!(
                &err,
                GraphError::ReleaseSelectionInvalid { package, reason: ReleaseSelectionInvalidReason::NoDispatchableTarget }
                    if package.name() == "pkg-a"
            ),
            "{err:?}"
        );
    }

    /// Selection is by exact `ecosystem/name`; a same-named package in another
    /// ecosystem, or a name absent from the workspace, never matches.
    #[test]
    fn selection_matches_exact_ecosystem_and_name_only() {
        let runner = empty_runner();
        let workspace = fixture_workspace(&runner, vec![publishing_cargo_package("pkg-a")]);
        for selection in [
            ReleasePackageId::new(Ecosystem::Npm, "pkg-a").unwrap(),
            ReleasePackageId::new(Ecosystem::Cargo, "pkg").unwrap(),
        ] {
            let err = derive_selected_release_decision(&workspace, &plan_bumping("pkg-a"), &[selection]).unwrap_err();
            assert!(matches!(err, GraphError::UnknownPackage { .. }), "{err:?}");
        }
        let exact = ReleasePackageId::new(Ecosystem::Cargo, "pkg-a").unwrap();
        let decision =
            derive_selected_release_decision(&workspace, &plan_bumping("pkg-a"), std::slice::from_ref(&exact)).unwrap();
        assert_eq!(decision.entries.len(), 1);
        assert_eq!(decision.entries[0].package, exact);
    }
}

item.aggregated_output:
//! Deterministic, graph-owned release roster decisions.
//!
//! It records the exact package/version authority that later intent construction consumes, without
//! exposing a mutation route.

use callisto_model::{
    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
    ReleaseInclusionReason, ReleasePackageId, Version,
};

use crate::error::{
    CommandFailure, CommitVerificationFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason,
    UnsupportedReleaseFeature,
};
use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};

/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
/// against `package`'s name.
///
/// This is the single derivation of release package identity shared by every
/// site that computes or verifies release authority: [`derive_release_decision`],
/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
/// Per this module's own established lesson (see the doc comment on
/// [`derive_release_commit_decision`]), independently reimplementing this
/// mapping at each call site is exactly the kind of duplicated derivation
/// that drifts -- so it lives here once instead.
pub(crate) fn release_package_ids(
    identity: &crate::IdentityIndex,
    package: &Package,
) -> Result<Vec<ReleasePackageId>, GraphError> {
    package
        .canonical_manifests()
        .map(|manifest| {
            let ecosystem = manifest.ecosystem();
            // A dual-manifest package's manifests may declare different names.
            let name = identity
                .native_name(&package.id, ecosystem)
                .unwrap_or(package.id.name());
            ReleasePackageId::new(ecosystem, name)
        })
        .collect::<Result<Vec<_>, _>>()
        .map_err(GraphError::from)
}

/// Derives the durable roster from a freshly computed version plan.
///
/// The caller supplies the plan from the same workspace observation; this
/// function never inspects a caller-provided release roster.
pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
) -> Result<ReleaseDecisionV1, GraphError> {
    let mut package_ids = std::collections::BTreeMap::new();
    for package in workspace.graph.packages() {
        let ids = release_package_ids(&workspace.identity, package)?;
        package_ids.insert(package.id.clone(), ids);
    }

    let mut entries = Vec::new();
    for bump in &plan.bumps {
        // `plan` is contractually derived from this same workspace
        // observation (see doc comment above), so every bump's package must
        // already be a key here -- a miss means the plan/workspace pairing
        // itself is inconsistent, not a recoverable operator condition.
        let ids = package_ids
            .get(&bump.package)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!(
                    "version plan references package `{}`, which is absent from this workspace observation",
                    bump.package.display_name()
                ),
            })?;
        for id in ids {
            entries.push(ReleaseDecisionEntry {
                package: id.clone(),
                target_version: bump.to.clone(),
                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
            });
        }
    }
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Derives a durable decision for explicit, exact release identities.
///
/// A linked group is one release unit: selecting any member includes every
/// member of that linked group which the version plan selected. All other
/// packages remain outside the authority boundary. The caller must pass
/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
/// for release authority.
pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
    selections: &[ReleasePackageId],
) -> Result<ReleaseDecisionV1, GraphError> {
    let complete = derive_release_decision(workspace, plan)?;

    let mut seen = std::collections::BTreeSet::new();
    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
        return Err(GraphError::ReleaseSelectionInvalid {
            package: duplicate.clone(),
            reason: ReleaseSelectionInvalidReason::Duplicate,
        });
    }

    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    for selection in &selected {
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        let reason = if !complete.entries.iter().any(|entry| &entry.package == *selection) {
            ReleaseSelectionInvalidReason::NotARelease
        } else if package
            .publish_to
            .iter()
            .all(|target| matches!(target, callisto_model::PublishTarget::None))
        {
            ReleaseSelectionInvalidReason::NoDispatchableTarget
        } else {
            continue;
        };
        return Err(GraphError::ReleaseSelectionInvalid {
            package: (*selection).clone(),
            reason,
        });
    }

    let entries = expand_selection(workspace, complete.entries, &selected);
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}

/// Keeps the selected entries plus every entry sharing a fixed or linked group
/// with a selection. Both release routes narrow `--package` through this.
fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    entries: Vec<ReleaseDecisionEntry>,
    selected: &std::collections::BTreeSet<&ReleasePackageId>,
) -> Vec<ReleaseDecisionEntry> {
    // A plan-derived entry carries its linked group as a reason.
    let reason_groups = entries
        .iter()
        .filter(|entry| selected.contains(&entry.package))
        .flat_map(|entry| entry.reasons.iter())
        .filter_map(|reason| match reason {
            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
            _ => None,
        })
        .collect::<std::collections::BTreeSet<_>>();
    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
    let config_groups = selected
        .iter()
        .flat_map(|selection| release_groups_of(workspace, selection))
        .collect::<std::collections::BTreeSet<_>>();
    entries
        .into_iter()
        .filter(|entry| {
            selected.contains(&entry.package)
                || entry.reasons.iter().any(|reason| {
                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
                })
                || release_groups_of(workspace, &entry.package)
                    .iter()
                    .any(|group| config_groups.contains(group))
        })
        .collect()
}

/// Derives the roster of every publishable package whose current version has
/// no tag in the canonical [`crate::TagIndex`], each with
/// [`ReleaseInclusionReason::UnreleasedVersion`].
///
/// A non-empty `selections` restricts the roster to exactly those identities,
/// each of which must be unreleased and publishable. `None` means nothing is
/// unreleased.
pub fn derive_unreleased_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
) -> Result<Option<ReleaseDecisionV1>, GraphError> {
    let versions = workspace.base_versions()?;
    let tags = workspace.tags()?;
    let mut entries = Vec::new();
    for package in workspace.graph.packages() {
        if !has_dispatchable_target(package) {
            continue;
        }
        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!("package `{}` has no base version", package.id.display_name()),
        })?;
        if version_is_tagged(tags, &package.id, version) {
            continue;
        }
        for id in release_package_ids(&workspace.identity, package)? {
            entries.push(ReleaseDecisionEntry {
                package: id,
                target_version: version.clone(),
                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
            });
        }
    }

    let mut seen = std::collections::BTreeSet::new();
    for selection in selections {
        if !seen.insert(selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::Duplicate,
            });
        }
        let Some(package) = workspace_package(workspace, selection) else {
            return Err(GraphError::UnknownPackage {
                id: callisto_model::PackageId::Prefixed {
                    ecosystem: selection.ecosystem(),
                    name: selection.name().to_string(),
                },
            });
        };
        if !has_dispatchable_target(package) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
            });
        }
        if !entries.iter().any(|entry| &entry.package == selection) {
            return Err(GraphError::ReleaseSelectionInvalid {
                package: selection.clone(),
                reason: ReleaseSelectionInvalidReason::NotARelease,
            });
        }
    }
    if !selections.is_empty() {
        entries = expand_selection(workspace, entries, &seen);
    }
    if entries.is_empty() {
        return Ok(None);
    }
    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
}

/// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
pub(crate) fn version_is_tagged(
    tags: &crate::TagIndex,
    package: &callisto_model::PackageId,
    version: &Version,
) -> bool {
    tags.contains_tag(&tags.template(package).render(version).to_string())
        || tags.last_tag(package).is_some_and(|tag| &tag.version == version)
}

pub(crate) fn has_dispatchable_target(package: &Package) -> bool {
    package
        .publish_to
        .iter()
        .any(|target| !matches!(target, callisto_model::PublishTarget::None))
}

/// The workspace package with this exact release identity.
fn workspace_package<'w, R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &'w Workspace<'_, R, D>,
    id: &ReleasePackageId,
) -> Option<&'w Package> {
    // By release identity, not name: a dual-manifest package's npm name can differ from its id.
    workspace
        .graph
        .packages()
        .find(|package| release_package_ids(&workspace.identity, package).is_ok_and(|ids| ids.contains(id)))
}

/// The fixed and linked groups a release package belongs to, per config.
fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    id: &ReleasePackageId,
) -> Vec<(&'static str, callisto_model::GroupName)> {
    let Some(package) = workspace_package(workspace, id) else {
        return Vec::new();
    };
    let groups = &workspace.config.groups;
    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
    // `member` keys are already canonical (`GroupTable::resolve` resolved
    // them through `IdentityIndex::resolve`), so exact equality is correct
    // here -- `PackageId::matches` would treat a Bare member key as an
    // ecosystem wildcard and could match a same-named package elsewhere.
    fixed
        .chain(linked)
        .filter(|(_, member, _)| **member == package.id)
        .map(|(kind, _, group)| (kind, group.clone()))
        .collect()
}

/// Verifies the release roster a merged release commit claims, against a
/// release-decision file committed alongside it at `decision_path`.
///
/// This is intentionally *not* a second computation of changeset, fixed-group,
/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
/// (via [`derive_release_decision`]) already computed that once, correctly,
/// when the release PR was generated -- and `callisto version --emit-decision`
/// commits its exact output alongside the manifest and changelog edits.
/// Re-deriving that policy a second time here, from raw git diffs, is exactly
/// the kind of duplicated logic that drifts: an earlier version of this
/// function did just that, understood only a direct changeset match, and
/// rejected every real release in this repository once a fixed-group cascade
/// (a case its reimplementation never learned) touched an unnamed sibling.
///
/// Instead, this function reads the committed decision back and confirms the
/// commit's actual diff matches it exactly -- no more, no less.
/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
/// entries don't match its content digest, so a hand-edited or corrupted
/// decision file fails before this function's own diff cross-check runs.
///
/// The caller must check out the exact merge commit in detached HEAD state
/// before creating an intent. GitHub-specific PR/approval provenance belongs
/// in the workflow boundary; this graph function verifies the local,
/// provider-neutral commit delta only.
pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    release_commit: &CommitSha,
    decision_path: &std::path::Path,
) -> Result<ReleaseDecisionV1, GraphError> {
    let head_args = ["rev-parse", "HEAD"];
    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
    let head =
        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
    if &head != release_commit {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::HeadMismatch,
        });
    }

    let parent_ref = format!("{}^", release_commit.as_str());
    let parent_args = ["rev-parse", parent_ref.as_str()];
    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;

    let diff_tree_args = [
        "diff-tree",
        "--no-commit-id",
        "--name-status",
        "-r",
        "--no-renames",
        parent.as_str(),
        release_commit.as_str(),
    ];
    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
    let changed = parse_name_status(&changed, &diff_tree_args)?;

    // The decision must be freshly authored as part of *this* commit, not a
    // stale leftover an earlier release already committed and this one never
    // touched -- otherwise a commit that changes nothing real could still
    // carry forward a prior, unrelated decision's authority.
    let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
    let decision_freshly_written = changed
        .iter()
        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
    if !decision_freshly_written {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
        });
    }

    // A cheap, independent sanity check that this commit is a real version
    // application and not just a hand-crafted decision file: some real
    // changeset was actually consumed. The decision's own entries, not this
    // changeset's content, remain the sole authority verified below.
    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
    let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
    let consumed_a_changeset = changed
        .iter()
        .any(|(status, path)| status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md"));
    if !consumed_a_changeset {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::NoChangesetConsumed,
        });
    }

    let decision_source = git_file(
        workspace.runner,
        &workspace.root,
        release_commit.as_str(),
        &decision_path_str,
    )?;
    let decision: ReleaseDecisionV1 =
        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
            path: decision_path.to_path_buf(),
            message: error.to_string(),
        })?;
    let claimed = decision
        .entries
        .iter()
        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
        .collect::<std::collections::BTreeMap<_, _>>();

    let changed_paths = changed
        .iter()
        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
        .collect::<std::collections::BTreeSet<_>>();

    // Every canonical manifest path this workspace currently declares, in
    // the exact order `workspace.graph.packages()` and
    // `Package::canonical_manifests()` yield -- both are backed by ordered
    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
    // the second traversal below visits the same (package, manifest) pairs
    // in the same order. That lets it zip the batched `before`/`after`
    // results back on by position instead of re-keying by path, which would
    // misbehave if two packages ever declared an identical manifest path.
    let manifest_queries: Vec<(String, Ecosystem)> = workspace
        .graph
        .packages()
        .flat_map(Package::canonical_manifests)
        .map(|manifest| (manifest.path.to_string_lossy().into_owned(), manifest.ecosystem()))
        .collect();
    let query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();

    // Exactly two `git cat-file --batch` subprocess invocations total (one
    // per commit), regardless of how many canonical manifests the
    // workspace has -- replaces what was previously 2*N separate `git
    // show` spawns (one `manifest_version_at` call per manifest per
    // commit).
    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
    let after_blobs =
        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
    let before_versions = resolve_batch_versions(before_blobs, &manifest_queries)?;
    let after_versions = resolve_batch_versions(after_blobs, &manifest_queries)?;

    let mut observed = std::collections::BTreeSet::new();
    let mut manifest_index = 0usize;
    for package in workspace.graph.packages() {
        let package_ids = release_package_ids(&workspace.identity, package)?;
        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
        if package_is_claimed {
            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
            })?;
            if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
                return Err(GraphError::ReleaseCommitVerificationFailed {
                    commit: release_commit.clone(),
                    reason: CommitVerificationFailure::ChangelogNotTouched,
                });
            }
        }
        for (manifest, id) in package.canonical_manifests().zip(package_ids) {
            let path = manifest.path.to_string_lossy();
            let before = &before_versions[manifest_index];
            let after = &after_versions[manifest_index];
            manifest_index += 1;
            let changed_version = before != after;
            match claimed.get(&id) {
                Some(target_version) => {
                    if !changed_paths.contains(path.as_ref()) {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestNotInDiff,
                        });
                    }
                    if !changed_version || after != target_version {
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::ManifestVersionMismatch,
                        });
                    }
                    observed.insert(id);
                }
                None => {
                    if changed_version {
                        // A changed version the committed decision never
                        // claimed is not this commit's authority -- fail
                        // closed rather than trust a partial match.
                        return Err(GraphError::ReleaseCommitVerificationFailed {
                            commit: release_commit.clone(),
                            reason: CommitVerificationFailure::UnclaimedVersionChange,
                        });
                    }
                }
            }
        }
    }
    if observed.len() != claimed.len() {
        return Err(GraphError::ReleaseCommitVerificationFailed {
            commit: release_commit.clone(),
            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
        });
    }

    Ok(decision)
}

/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation that
/// exited non-zero, carrying its real exit status and stderr instead of
/// discarding them.
fn command_non_zero_exit(program: &str, args: &[&str], output: &callisto_model::CommandOutput) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::NonZeroExit {
            exit_code: output.exit_code,
            stderr: output.stderr.clone(),
        },
    }
}

/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation whose
/// output could not be parsed into the shape this module expects.
fn command_malformed_output(program: &str, args: &[&str], detail: impl Into<String>) -> GraphError {
    GraphError::ReleaseCommand {
        program: program.to_string(),
        args: args.iter().map(|s| s.to_string()).collect(),
        failure: CommandFailure::MalformedOutput { detail: detail.into() },
    }
}

fn git_stdout<R: CommandRunner>(runner: &R, root: &std::path::Path, args: &[&str]) -> Result<String, GraphError> {
    let output = runner.run_with_timeout("git", args, root, super::release::timeouts::LOCAL_GIT)?;
    if !output.success() {
        return Err(command_non_zero_exit("git", args, &output));
    }
    Ok(output.stdout_trimmed().to_string())
}

fn parse_name_status(output: &str, args: &[&str]) -> Result<Vec<(String, String)>, GraphError> {
    output
        .lines()
        .map(|line| {
            let (status, path) = line.split_once('\t').ok_or_else(|| {
                command_malformed_output(
                    "git",
                    args,
                    format!("name-status line missing a tab separator: `{line}`"),
                )
            })?;
            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
                return Err(command_malformed_output(
                    "git",
                    args,
                    format!("name-status reported an unexpected status/path: `{status}` `{path}`"),
                ));
            }
            Ok((status.to_string(), path.to_string()))
        })
        .collect()
}

fn git_file<R: CommandRunner>(
    runner: &R,
    root: &std::path::Path,
    commit: &str,
    path: &str,
) -> Result<String, GraphError> {
    let object = format!("{commit}:{path}");
    git_stdout(runner, root, &["show", &object])
}

/// Extracts a manifest's declared version from its already-fetched raw
/// source text. Shared by the batched `git cat-file --batch` path in
/// [`derive_release_commit_decision`] (via [`resolve_batch_versions`]) and
/// this module's own tests (via the single-object `manifest_version_at`
/// helper they define), so both use identical parsing rules.
fn parse_manifest_version(source: &str, path: &str, ecosystem: Ecosystem) -> Result<Version, GraphError> {
    // Every canonical manifest this module ever queries comes from
    // `Package::canonical_manifests()`, which (per `walk.rs`) only ever
    // constructs a `Canonical`-role declaration for Cargo.toml/package.json/
    // pyproject.toml -- the three formats whose ecosystem always has a
    // `canonical_manifest_format`. A miss here means that upstream
    // invariant broke, not that this particular manifest is unsupported.
    let format = ecosystem
        .canonical_manifest_format()
        .ok_or_else(|| GraphError::ReleaseInvariant {
            detail: format!(
                "canonical manifest `{path}` has ecosystem `{}`, which has no canonical manifest format",
                ecosystem.prefix()
            ),
        })?;
    // A malformed blob, a version-less manifest (e.g. a Cargo workspace
    // root with no [package] table, or a `dynamic = ["version"]` PEP 621
    // package), or a Cargo `version.workspace = true` inheritance (which
    // `read_identity` deliberately never resolves, having no workspace
    // context for a historical git blob) all fail closed here rather than
    // panicking or fabricating a version.
    let version = callisto_manifests::read_identity(format, source, std::path::Path::new(path))
        .ok()
        .and_then(|identity| match identity.version {
            Some(callisto_manifests::VersionSource::Literal(v)) => Some(v),
            _ => None,
        })
        .ok_or_else(|| {
            command_malformed_output(
                "git",
                &["cat-file", "--batch"],
                format!("manifest `{path}` has no literal declared version"),
            )
        })?;
    Version::parse(&version, ecosystem.version_grammar()).map_err(GraphError::from)
}

/// One object's content as reported by `git cat-file --batch`, for a single
/// requested `<commit>:<path>`.
enum BatchBlob {
    /// The path resolved to a blob at the queried commit; this is its raw
    /// content.
    Blob(String),
    /// The path did not exist at the queried commit -- e.g. a package's
    /// manifest that was only added later, so it has no blob yet at an
    /// earlier `parent` commit.
    Missing,
}

/// Issues exactly one `git cat-file --batch` invocation requesting every
/// path in `paths` as `<commit>:<path>`, and returns each result in the
/// same order as `paths`.
///
/// `git cat-file --batch` reads one object identifier per line from stdin
/// and, for each, writes to stdout either:
///
/// ```text
/// <sha> SP <type> SP <size> LF
/// <content: exactly `size` bytes> LF
/// ```
///
/// or, if the object doesn't exist:
///
/// ```text
/// <object> SP missing LF
/// ```
///
/// (git also reports `<object> SP ambiguous LF` for a ref that resolves to
/// more than one object; `<commit>:<path>` syntax should never be
/// ambiguous, but it's checked for explicitly below rather than silently
/// falling through to the blob-header parse.)
///
/// This lets every canonical manifest's content at one commit be fetched in
/// a single subprocess round trip instead of one `git show` per manifest.
///
/// Parsing here is deliberately defensive rather than permissive: this
/// feeds [`derive_release_commit_decision`]'s trust-boundary comparison, so
/// any framing ambiguity -- an unrecognized header shape, a declared `size`
/// that doesn't fit the remaining output, a missing separator byte right
/// after the declared content length, a non-`blob` object type, or a
/// leftover/truncated tail once every requested path has been accounted
/// for -- fails the whole batch closed rather than guessing. Each expected
/// response is also matched against its exact requested object string
/// (rather than a generic "ends with ` missing`" pattern), so a manifest
/// path that happened to contain a space or colon can't be misread as a
/// different response shape. Silently misattributing one manifest's
/// content to a different path because an undetected desync shifted every
/// later offset would be a far worse failure mode than an outright
/// rejection.
fn batch_manifest_blobs_at<R: CommandRunner>(
    runner: &R,
    root: &std::path::Path,
    commit: &str,
    paths: &[&str],
) -> Result<Vec<BatchBlob>, GraphError> {
    if paths.is_empty() {
        return Ok(Vec::new());
    }

    const BATCH_ARGS: [&str; 2] = ["cat-file", "--batch"];

    let mut stdin = String::new();
    let objects: Vec<String> = paths
        .iter()
        .map(|path| {
            let object = format!("{commit}:{path}");
            stdin.push_str(&object);
            stdin.push('\n');
            object
        })
        .collect();

    let output = runner.run_with_stdin("git", &BATCH_ARGS, root, stdin.as_bytes())?;
    if !output.success() {
        return Err(command_non_zero_exit("git", &BATCH_ARGS, &output));
    }

    let mut rest = output.stdout.as_str();
    let mut results = Vec::with_capacity(objects.len());
    for object in &objects {
        let (header, after_header) = rest.split_once('\n').ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("truncated response: missing header line for `{object}`"),
            )
        })?;

        if header == format!("{object} missing") {
            results.push(BatchBlob::Missing);
            rest = after_header;
            continue;
        }
        if header == format!("{object} ambiguous") {
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` is ambiguous"),
            ));
        }

        let mut fields = header.split(' ');
        let sha = fields.next().ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` is missing its sha field: `{header}`"),
            )
        })?;
        let object_type = fields.next().ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` is missing its type field: `{header}`"),
            )
        })?;
        let size_field = fields.next().ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` is missing its size field: `{header}`"),
            )
        })?;
        if fields.next().is_some() {
            // A well-formed header has exactly three space-separated
            // fields; anything else is not a shape this parser understands.
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` has more than three fields: `{header}`"),
            ));
        }
        if sha.is_empty() || !sha.chars().all(|c| c.is_ascii_hexdigit()) {
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` reports a non-hex sha: `{sha}`"),
            ));
        }
        if object_type != "blob" {
            // Every path requested here is a canonical manifest file, so a
            // resolved object must be a blob; a tree/commit/tag response
            // means the path resolved to something else entirely.
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` resolved to a `{object_type}`, not a blob"),
            ));
        }
        let size: usize = size_field.parse().map_err(|parse_error| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("header for `{object}` has a non-numeric size `{size_field}`: {parse_error}"),
            )
        })?;

        if size > after_header.len() {
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` declares size {size}, exceeding the remaining response"),
            ));
        }
        // `.get(..size)` (byte-indexed) rather than raw slicing: if `size`
        // doesn't land on a UTF-8 char boundary this fails closed instead
        // of panicking.
        let content = after_header.get(..size).ok_or_else(|| {
            command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` declares size {size} that does not land on a UTF-8 boundary"),
            )
        })?;
        let remainder = &after_header[size..];
        // The protocol always emits exactly one LF right after the
        // content, separate from the content itself. Requiring it here
        // catches a desynced `size` (from an earlier, unexpectedly
        // reencoded entry) as an explicit error instead of silently
        // parsing the wrong bytes as this entry's content.
        if remainder.as_bytes().first() != Some(&b'\n') {
            return Err(command_malformed_output(
                "git",
                &BATCH_ARGS,
                format!("object `{object}` content is not followed by the expected newline separator"),
            ));
        }
        results.push(BatchBlob::Blob(content.to_string()));
        rest = &remainder[1..];
    }

    if !rest.is_empty() {
        // More output than the requested objects account for -- either an
        // extra unexpected reply or a framing desync earlier in the
        // stream. Either way, fail closed rather than ignore it.
        return Err(command_malformed_output(
            "git",
            &BATCH_ARGS,
            "response contained more data than the requested objects account for",
        ));
    }

    Ok(results)
}

/// Converts each batched blob-fetch result into the [`Version`] the
/// equivalent single-object `git show` fetch would have produced, using
/// [`parse_manifest_version`]'s parsing rules. A path missing from the
/// queried commit fails closed exactly as a `git show` that couldn't
/// resolve the path would have.
fn resolve_batch_versions(blobs: Vec<BatchBlob>, queries: &[(String, Ecosystem)]) -> Result<Vec<Version>, GraphError> {
    blobs
        .into_iter()
        .zip(queries.iter())
        .map(|(blob, (path, ecosystem))| match blob {
            BatchBlob::Blob(source) => parse_manifest_version(&source, path, *ecosystem),
            BatchBlob::Missing => Err(command_malformed_output(
                "git",
                &["cat-file", "--batch"],
                format!("canonical manifest `{path}` was reported missing at the queried commit"),
            )),
        })
        .collect()
}

fn reason_from_bump(
    reason: Option<&BumpReason>,
    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
) -> Result<ReleaseInclusionReason, GraphError> {
    match reason {
        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
            group_id: group.to_string(),
        }),
        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
            Ok(ReleaseInclusionReason::FixedGroup {
                group_id: group.to_string(),
            })
        }
        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
            // `package_ids` is derived from the same workspace graph `via`
            // was resolved against, so a miss (or a non-unique release
            // identity) here means that pairing broke, not that this is a
            // recoverable operator condition.
            let source = package_ids
                .get(via)
                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!(
                        "cascade source package `{}` has no unique release package id",
                        via.display_name()
                    ),
                })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: format!("{dep_kind:?}"),
            })
        }
        Some(BumpReason::PeerEscalation { via, .. }) => {
            let source = package_ids
                .get(via)
                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!(
                        "peer-escalation source package `{}` has no unique release package id",
                        via.display_name()
                    ),
                })?;
            Ok(ReleaseInclusionReason::Cascade {
                from: source,
                edge_kind: "peer".to_string(),
            })
        }
        Some(_) => Err(GraphError::UnsupportedRelease {
            feature: UnsupportedReleaseFeature::BumpReason,
        }),
    }
}

