                stderr_of(&result).contains(expected),
                "unexpected {case} diagnostic: {}",
                stderr_of(&result)
            );
            assert!(diagnostic_codes(&result).iter().any(|code| code == "E166"));
            assert!(!out.exists(), "invalid Python {case} must not authorize execution");
        }
    }

