        wire["entries"][0]["package"] = "npm/stable-python".into();
        let entry: callisto_model::ReleaseDecisionEntry = serde_json::from_value(wire["entries"][0].clone()).unwrap();
        let forged = ReleaseDecisionV1::new(vec![entry]).unwrap();
