    let mut missing_reason = decision.clone();
    missing_reason["entries"][0]["reasons"] = serde_json::json!([]);
    assert!(serde_json::from_value::<ReleaseDecisionV1>(missing_reason).is_err());
    let mut duplicate = decision;
