    assert!(serde_json::from_value::<ReleaseIntentV1>(changed).is_err());
    let mut changed = wire.clone();
    changed["trustProfile"] = serde_json::json!("hermeticContent");
    assert!(serde_json::from_value::<ReleaseIntentV1>(changed).is_err());
    let mut changed = wire;
    changed["schemaVersion"] = serde_json::json!(9);
    assert!(serde_json::from_value::<ReleaseIntentV1>(changed).is_err());
}

